function requiredTechniqueIds(graph,techniqueId){return graph.relations.filter((edge)=>edge.type==='requires'&&edge.from===techniqueId&&edge.to.startsWith('technique.')).map((edge)=>edge.to);}
export function composeTechniqueDag(graph,ranked,targetOutcomeIds){const selected=[];const byId=new Map(ranked.map((item)=>[item.id,item]));const visiting=new Set();function add(id){if(selected.some((item)=>item.id===id))return;if(visiting.has(id))throw new Error(`Technique dependency cycle: ${id}`);const item=byId.get(id);if(!item)return;visiting.add(id);for(const dependency of requiredTechniqueIds(graph,id))add(dependency);visiting.delete(id);selected.push(item);}for(const outcomeId of targetOutcomeIds){const candidate=ranked.find((item)=>item.mappedOutcomes.includes(outcomeId));if(candidate)add(candidate.id);}if(!selected.length&&ranked[0])add(ranked[0].id);const steps=selected.map((item,index)=>({stepId:`step-${index+1}`,techniqueId:item.id,providerId:item.provider.providerId,outcomeIds:item.mappedOutcomes,dependsOn:requiredTechniqueIds(graph,item.id).map((id)=>selected.find((item)=>item.id===id)).filter(Boolean).map((item)=>item.id),score:Number(item.score.toFixed(6))}));const independent=steps.filter((step)=>!step.dependsOn.length);const executionGroups=[];if(independent.length>1)executionGroups.push({mode:'parallel',stepIds:independent.map((step)=>step.stepId)});else if(steps.length)executionGroups.push({mode:'sequential',stepIds:steps.map((step)=>step.stepId)});return{steps,executionGroups};}
